def compute_social_influence(neighbors_adopting: float, peer_weight: float, attitude: float, stubbornness: float) -> float:
    # Update attitude toward neighbor average with stubbornness damping
    delta = peer_weight * (2 * neighbors_adopting - 1.0)  # map [0,1] -> [-1,1]
    return max(-1.0, min(1.0, attitude * (1 - stubbornness) + delta * stubbornness))

def compute_validations(adoption_series: List[float]) -> Dict[str, Any]:
    eps = 1e-3
    window = 7
    steady = False
    if len(adoption_series) >= window + 1:
        diffs = [abs(adoption_series[i] - adoption_series[i-1]) for i in range(1, len(adoption_series))]
        steady = all(d < eps for d in diffs[-window:])
    return {
        'steady_state_reached': steady,
        'constraints_respected': all(0.0 <= v <= 1.0 for v in adoption_series),
        'logistic_shape_fit': None  # optional, behind a flag
    }
